import React, { useState, useEffect } from 'react';

const ProductModal = ({ isOpen, onClose, onSubmit, initialData }) => {
    const [formData, setFormData] = useState({
        title: '', category: 'GPU', price: '', description: '', stock: '0'
    });

    useEffect(() => {
        if (initialData) {
            setFormData({ ...initialData });
        } else {
            setFormData({ title: '', category: 'GPU', price: '', description: '', stock: '0' });
        }
    }, [initialData, isOpen]);

    if (!isOpen) return null;

    const handleSubmit = (e) => {
        e.preventDefault();
        onSubmit(formData);
    };

    return (
        <div className="modal-overlay" onClick={onClose}>
            <div className="modal-content" onClick={e => e.stopPropagation()}>
                <div className="modal-header">
                    <h2>{initialData ? 'Редактировать товар' : 'Новый товар'}</h2>
                    <button className="close-btn" onClick={onClose}>✕</button>
                </div>
                
                <form onSubmit={handleSubmit}>
                    <div className="form-group">
                        <label>Название *</label>
                        <input required type="text" value={formData.title} onChange={e => setFormData({...formData, title: e.target.value})} />
                    </div>
                    
                    <div className="form-row">
                        <div className="form-group">
                            <label>Категория *</label>
                            <select value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})}>
                                <option value="GPU">GPU</option>
                                <option value="CPU">CPU</option>
                                <option value="SSD">SSD</option>
                                <option value="RAM">RAM</option>
                            </select>
                        </div>
                        <div className="form-group">
                            <label>Цена (₽) *</label>
                            <input required type="number" min="1" value={formData.price} onChange={e => setFormData({...formData, price: e.target.value})} />
                        </div>
                        <div className="form-group">
                            <label>Наличие (шт)</label>
                            <input type="number" min="0" value={formData.stock} onChange={e => setFormData({...formData, stock: e.target.value})} />
                        </div>
                    </div>

                    <div className="form-group">
                        <label>Описание *</label>
                        <textarea required minLength="10" rows="3" value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} />
                    </div>

                    <div className="modal-footer">
                        <button type="button" className="btn-cancel" onClick={onClose}>Отмена</button>
                        <button type="submit" className="btn-save">Сохранить</button>
                    </div>
                </form>
            </div>
        </div>
    );
};

export default ProductModal;
